exercises.solutionCode:
typedef struct {
    int text_kb;
    int data_kb;
    int bss_kb;
    int stack_kb;
} SectionUsage;

int check_memory_fit(const SectionUsage *u, int flash_kb, int ram_kb)
{
    if (u == NULL || flash_kb < 0 || ram_kb < 0) {
        return -1;
    }
    if (u->text_kb < 0 || u->data_kb < 0 || u->bss_kb < 0 || u->stack_kb < 0) {
        return -1;
    }

    int flash_used = u->text_kb + u->data_kb;
    int ram_used = u->data_kb + u->bss_kb + u->stack_kb;
    int flash_over = (flash_used > flash_kb) ? 1 : 0;
    int ram_over = (ram_used > ram_kb) ? 1 : 0;

    return flash_over + (ram_over << 1);
}
